def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix (i.e., []) has determinant 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square (assume input is valid as per spec)
    if n == 1:
        return matrix[0][0]
    # Recursive expansion by first row
    def det(mat):
        size = len(mat)
        if size == 1:
            return mat[0][0]
        if size == 2:
            return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0]
        total = 0
        for col in range(size):
            # Build submatrix excluding row 0 and column col
            sub = [row[:col] + row[col+1:] for row in mat[1:]]
            sign = -1 if col % 2 else 1
            total += sign * mat[0][col] * det(sub)
        return total
    return det(matrix)

