def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix (i.e., []) has determinant 1.
    Uses the fraction-free Bareiss algorithm for exact integer results.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    if n == 1:
        return matrix[0][0]
    # Verify square matrix (defensive)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a deep copy to avoid mutating input
    A = [list(row) for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Pivot handling: if pivot is zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update (guaranteed divisible)
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]

