def solve(s: str) -> int:
    """Return the length of the longest substring of *s* that contains no repeated characters.
    Uses a sliding‑window with a dictionary that stores the most recent index of each character.
    """
    last_seen = {}
    max_len = 0
    start = 0  # beginning of the current window
    for i, ch in enumerate(s):
        # If ch was seen inside the current window, move the start just after its previous occurrence.
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

