    for p in range(2, int(math.isqrt(limit)) + 1):
        if is_prime[p]:
            step = p
            start = p * p
            is_prime[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(is_prime)

def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    The algorithm follows the classic LeetCode "Simplify Path" solution.
    """
    # Ensure it's a string; if not, treat as empty path
    if not isinstance(path, str):
        return '/'
    # Split on '/', filter out empty parts and '.'
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty we stay at root
        else:
            stack.append(part)
    # Build the canonical path
    result = '/' + '/'.join(stack)
    # Ensure root is exactly '/'
    return result if result != '' else '/'

