def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles edge cases such as None or empty input gracefully.
    Uses the patience sorting algorithm (O(n log n)).
    """
    if not nums:
        return 0
    # Ensure we have a list to iterate over
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []
    for x in nums:
        # Skip non‑numeric entries safely
        try:
            # x must support comparison; if not, treat as not extending sequence
            idx = bisect.bisect_left(tails, x)
        except Exception:
            continue
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

