def solve(a, b):
    # classic DP edit distance (Levenshtein) with insertion, deletion, substitution cost 1
    m, n = len(a), len(b)
    # ensure the smaller dimension for memory efficiency
    if n < m:
        a, b = b, a
        m, n = n, m
    # dp[j] = distance for a[:i] to b[:j]
    dp = list(range(n+1))
    for i in range(1, m+1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n+1):
            cur = dp[j]
            if a[i-1] == b[j-1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j-1], dp[j])  # substitution, insertion, deletion
            prev = cur
    return dp[n]

