def solve(weights, values, capacity):
    """0/1 knapsack returning the maximum total value.
    Handles edge cases such as mismatched input lengths, negative or zero capacity,
    and ignores items with non‑positive weight (weight <= 0)."""
    if capacity <= 0:
        return 0
    # Ensure we only iterate over pairs that exist
    n = min(len(weights), len(values))
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w <= 0:
            # Zero or negative weight: we can always take it (once), add its value to all states
            # Avoid infinite loop by adding value directly to each dp entry
            for cur in range(capacity + 1):
                dp[cur] += v
            continue
        if w > capacity:
            continue
        # Update dp backwards to prevent reuse of the same item
        for cur in range(capacity, w - 1, -1):
            new_val = dp[cur - w] + v
            if new_val > dp[cur]:
                dp[cur] = new_val
    return dp[capacity]

