def solve(words, width):
    lines = []
    current = ''
    for w in words:
        if w == '':
            # skip empty words as they don't contribute characters
            continue
        if not current:
            # start new line with w
            current = w
        else:
            # try to add with space
            if len(current) + 1 + len(w) <= width:
                current += ' ' + w
            else:
                lines.append(current)
                current = w
        # If the current word alone exceeds width, we still keep it as a line (handled by next iteration)
    if current:
        lines.append(current)
    return lines

def solve(weights, values, capacity):
    # 0/1 knapsack DP using 1D array
    n = len(weights)
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reuse
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

