    Uses the Bareiss algorithm for exact integer arithmetic (no floating point).
    An empty matrix is defined to have determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Copy to avoid mutating input
    A = [list(row) for row in matrix]
    sign = 1
    for k in range(n - 1):
        # Pivot selection: if zero, swap with a lower row that has non-zero in column k
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
    return sign * A[n - 1][n - 1]
